package com.tsk.carmedia
import android.app.*;import android.content.*;import android.graphics.*;import android.hardware.display.DisplayManager;import android.media.*;import android.media.projection.*;import android.os.*;import androidx.core.app.NotificationCompat;import java.io.ByteArrayOutputStream;import java.net.*;import java.nio.ByteBuffer;import java.util.concurrent.Executors;import java.util.concurrent.atomic.*
class MirrorService:Service(){var mp:MediaProjection?=null;var rd:ImageReader?=null;var vd:android.hardware.display.VirtualDisplay?=null;val ex=Executors.newSingleThreadExecutor();val busy=AtomicBoolean(false);val latest=AtomicReference<ByteArray?>(null);var ip="";var seq=0;var sent=0L;var captured=0L;var jpegSize=0;var started=0L;var last=0L;var err=""
override fun onBind(i:Intent?)=null
override fun onStartCommand(i:Intent?,f:Int,id:Int):Int{started=System.nanoTime();val nm=getSystemService(NOTIFICATION_SERVICE) as NotificationManager;nm.createNotificationChannel(NotificationChannel("cm","Car Media",NotificationManager.IMPORTANCE_LOW));startForeground(1,note("Diagnostic active"));ip=i!!.getStringExtra("ip")!!;@Suppress("DEPRECATION") val data=i.getParcelableExtra<Intent>("data")!!;try{mp=(getSystemService(MEDIA_PROJECTION_SERVICE) as MediaProjectionManager).getMediaProjection(i.getIntExtra("code",0),data);mp!!.registerCallback(object:MediaProjection.Callback(){override fun onStop(){stopSelf()}},Handler(Looper.getMainLooper()));rd=ImageReader.newInstance(960,360,PixelFormat.RGBA_8888,2);vd=mp!!.createVirtualDisplay("CarMedia",960,360,180,DisplayManager.VIRTUAL_DISPLAY_FLAG_AUTO_MIRROR,rd!!.surface,null,null);rd!!.setOnImageAvailableListener({r->val now=System.nanoTime();val im=r.acquireLatestImage()?:return@setOnImageAvailableListener;if(now-last<50_000_000L){im.close();return@setOnImageAvailableListener};last=now;captured++;try{val p=im.planes[0];val pad=p.rowStride-p.pixelStride*im.width;val w=Bitmap.createBitmap(im.width+pad/p.pixelStride,im.height,Bitmap.Config.ARGB_8888);w.copyPixelsFromBuffer(p.buffer);val b=Bitmap.createBitmap(w,0,0,im.width,im.height);w.recycle();val o=ByteArrayOutputStream();b.compress(Bitmap.CompressFormat.JPEG,30,o);b.recycle();val j=o.toByteArray();jpegSize=j.size;latest.set(j);pump();status()}catch(e:Exception){err=e.toString();status()}finally{im.close()}},Handler(Looper.getMainLooper()));status()}catch(e:Exception){err=e.toString();status()};return START_NOT_STICKY}
fun pump(){if(!busy.compareAndSet(false,true))return;ex.execute{val s=DatagramSocket();try{while(true){val j=latest.getAndSet(null)?:break;seq++;val c=58000;val total=(j.size+c-1)/c;for(n in 0 until total){val a=n*c;val z=minOf(j.size,a+c);val h=ByteBuffer.allocate(16).putInt(0x434D3134).putInt(seq).putInt(n).putInt(total).array();val out=ByteArray(16+z-a);System.arraycopy(h,0,out,0,16);System.arraycopy(j,a,out,16,z-a);s.send(DatagramPacket(out,out.size,InetAddress.getByName(ip),8766))};sent++;status()}}catch(e:Exception){err=e.toString();status()}finally{s.close();busy.set(false);if(latest.get()!=null)pump()}}}
fun status(){val sec=(System.nanoTime()-started)/1e9;val fps=if(sec>0)captured/sec else 0.0;val t="CAPTURE: ${if(captured>0)"OK ✓ ($captured)" else "WAITING"}\nJPEG: $jpegSize bytes\nUDP SENT: $sent\nFPS: %.1f\nPC IP: $ip${if(err.isNotEmpty())"\nERROR: $err" else ""}".format(fps);sendBroadcast(Intent("com.tsk.carmedia.STATUS").setPackage(packageName).putExtra("text",t));(getSystemService(NOTIFICATION_SERVICE) as NotificationManager).notify(1,note("Capture $captured • UDP $sent"))}
fun note(x:String)=NotificationCompat.Builder(this,"cm").setContentTitle("Car Media v1.4.1").setContentText(x).setSmallIcon(android.R.drawable.ic_media_play).setOnlyAlertOnce(true).build()
override fun onDestroy(){rd?.close();vd?.release();mp?.stop();ex.shutdownNow();super.onDestroy()}}